"""Recover pooled-spectrum macros from the saved report, without rerunning analysis."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
source = ROOT / 'thesis/generated/ch3_revision.json'
raw = source.read_bytes()
report = json.loads(raw)
lines = [
    '% Generated by revisions/thesis-experiments-split-2026-09-17/recover_pooled_values.py',
    '% Source: thesis/generated/ch3_revision.json',
    '% SHA256: ' + hashlib.sha256(raw).hexdigest(),
    '% Provide only missing macros; current reporter outputs take precedence.',
]
for discipline, tag in [('paragliders', 'Para'), ('hang gliders', 'Hang')]:
    nu = [z / q for z, q in zip(report['results'][discipline]['zeta'], report['q'], strict=True)]
    for suffix, value in [('Min', min(nu)), ('Max', max(nu))]:
        lines.append(r'\providecommand{\StatRev' + tag + 'PooledMomentNu' + suffix + '}{' + f'{value:.3f}' + '}')
(ROOT / 'thesis/generated/ch3_pooled_moment_values.tex').write_text('\n'.join(lines) + '\n')
